-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_attendance AS SELECT attendance.link_to_event AS link_to_event, attendance.link_to_member AS link_to_member, link_to_member.first_name AS first_name, link_to_member.last_name AS last_name, link_to_member.email AS email, link_to_member.position AS position, link_to_member.t_shirt_size AS t_shirt_size, link_to_member.phone AS phone, link_to_member.zip AS zip, link_to_member.link_to_major AS link_to_major, link_to_member_zip.type AS type, link_to_member_zip.city AS city, link_to_member_zip.county AS county, link_to_member_zip.state AS state, link_to_member_zip.short_state AS short_state, link_to_member_link_to_major.major_name AS major_name, link_to_member_link_to_major.department AS department, link_to_member_link_to_major.college AS college, link_to_event.event_name AS event_name, link_to_event.event_date AS event_date, link_to_event.type AS link_to_event_type, link_to_event.notes AS notes, link_to_event.location AS location, link_to_event.status AS status FROM attendance LEFT JOIN member AS link_to_member ON attendance.link_to_member = link_to_member.member_id LEFT JOIN zip_code AS link_to_member_zip ON link_to_member.zip = link_to_member_zip.zip_code LEFT JOIN major AS link_to_member_link_to_major ON link_to_member.link_to_major = link_to_member_link_to_major.major_id LEFT JOIN event AS link_to_event ON attendance.link_to_event = link_to_event.event_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_budget AS SELECT budget.budget_id AS budget_id, budget.category AS category, budget.spent AS spent, budget.remaining AS remaining, budget.amount AS amount, budget.event_status AS event_status, budget.link_to_event AS link_to_event, link_to_event.event_name AS event_name, link_to_event.event_date AS event_date, link_to_event.type AS type, link_to_event.notes AS notes, link_to_event.location AS location, link_to_event.status AS status FROM budget LEFT JOIN event AS link_to_event ON budget.link_to_event = link_to_event.event_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_expense AS SELECT expense.expense_id AS expense_id, expense.expense_description AS expense_description, expense.expense_date AS expense_date, expense.cost AS cost, expense.approved AS approved, expense.link_to_member AS link_to_member, expense.link_to_budget AS link_to_budget, link_to_member.first_name AS first_name, link_to_member.last_name AS last_name, link_to_member.email AS email, link_to_member.position AS position, link_to_member.t_shirt_size AS t_shirt_size, link_to_member.phone AS phone, link_to_member.zip AS zip, link_to_member.link_to_major AS link_to_major, link_to_member_zip.type AS type, link_to_member_zip.city AS city, link_to_member_zip.county AS county, link_to_member_zip.state AS state, link_to_member_zip.short_state AS short_state, link_to_member_link_to_major.major_name AS major_name, link_to_member_link_to_major.department AS department, link_to_member_link_to_major.college AS college, link_to_budget.category AS category, link_to_budget.spent AS spent, link_to_budget.remaining AS remaining, link_to_budget.amount AS amount, link_to_budget.event_status AS event_status, link_to_budget.link_to_event AS link_to_event, link_to_budget_link_to_event.event_name AS event_name, link_to_budget_link_to_event.event_date AS event_date, link_to_budget_link_to_event.type AS link_to_budget_link_to_event_type, link_to_budget_link_to_event.notes AS notes, link_to_budget_link_to_event.location AS location, link_to_budget_link_to_event.status AS status FROM expense LEFT JOIN member AS link_to_member ON expense.link_to_member = link_to_member.member_id LEFT JOIN zip_code AS link_to_member_zip ON link_to_member.zip = link_to_member_zip.zip_code LEFT JOIN major AS link_to_member_link_to_major ON link_to_member.link_to_major = link_to_member_link_to_major.major_id LEFT JOIN budget AS link_to_budget ON expense.link_to_budget = link_to_budget.budget_id LEFT JOIN event AS link_to_budget_link_to_event ON link_to_budget.link_to_event = link_to_budget_link_to_event.event_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_income AS SELECT income.income_id AS income_id, income.date_received AS date_received, income.amount AS amount, income.source AS source, income.notes AS notes, income.link_to_member AS link_to_member, link_to_member.first_name AS first_name, link_to_member.last_name AS last_name, link_to_member.email AS email, link_to_member.position AS position, link_to_member.t_shirt_size AS t_shirt_size, link_to_member.phone AS phone, link_to_member.zip AS zip, link_to_member.link_to_major AS link_to_major, link_to_member_zip.type AS type, link_to_member_zip.city AS city, link_to_member_zip.county AS county, link_to_member_zip.state AS state, link_to_member_zip.short_state AS short_state, link_to_member_link_to_major.major_name AS major_name, link_to_member_link_to_major.department AS department, link_to_member_link_to_major.college AS college FROM income LEFT JOIN member AS link_to_member ON income.link_to_member = link_to_member.member_id LEFT JOIN zip_code AS link_to_member_zip ON link_to_member.zip = link_to_member_zip.zip_code LEFT JOIN major AS link_to_member_link_to_major ON link_to_member.link_to_major = link_to_member_link_to_major.major_id;

-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_member AS SELECT member.member_id AS member_id, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, zip.type AS type, zip.city AS city, zip.county AS county, zip.state AS state, zip.short_state AS short_state, link_to_major.major_name AS major_name, link_to_major.department AS department, link_to_major.college AS college FROM member LEFT JOIN zip_code AS zip ON member.zip = zip.zip_code LEFT JOIN major AS link_to_major ON member.link_to_major = link_to_major.major_id;
